message.content:
{
  "definition_simple": "競技や戦いで、互いの実力が接近していて、どちらが勝つかわからないこと。",
  "definition_standard": "互いの力が拮抗していて、僅差の争いになっている試合や戦い。特にスポーツなどで、勝敗が最後までわからない緊迫した状況を指す。",
  "pos": "名詞・サ変・自動",
  "semantic_class": "action",
  "sentences": [
    {"sentence": "昨日の試合は接戦だった。", "tier": "T1"},
    {"sentence": "このチームとの接戦が楽しみだ。", "tier": "T1"},
    {"sentence": "両チームが接戦を繰り広げた。", "tier": "T2"},
    {"sentence": "接戦に勝って、次のラウンドに進んだ。", "tier": "T2"},
    {"sentence": "最後まで接戦が続き、観客は興奮した。", "tier": "T3"},
    {"sentence": "接戦を制したのは、経験豊富な選手たちだった。", "tier": "T3"},
    {"sentence": "彼らの接戦は、歴史に残る名試合となった。", "tier": "T4"},
    {"sentence": "あの接戦で見せた粘り強さが、成長につながった。", "tier": "T4"},
    {"sentence": "終盤まで接戦を強いられたが、チームは集中力を切らさなかった。", "tier": "T5"},
    {"sentence": "両雄が激突し、一進一退の接戦が延長戦までもつれ込んだ。", "tier": "T6"}
  ],
  "morphological_forms": [
    {"form": "接戦した", "label": "past_tense"},
    {"form": "接戦して", "label": "te_form"}
  ],
  "morphology_wrong_forms": [
    {
      "real_form": "接戦した",
      "wrong_forms": [
        {"form": "接戦しった", "explanation": "「する」の連用形「し」に促音便を誤って適用した形。正しくは「した」。"},
        {"form": "接戦したた", "explanation": "過去の助動詞「た」を重複させた誤り。"},
        {"form": "接戦しだ", "explanation": "語尾の無声化を誤って有声化した形。"}
      ]
    },
    {
      "real_form": "接戦して",
      "wrong_forms": [
        {"form": "接戦しって", "explanation": "促音便の誤用で、正しくは「して」。"},
        {"form": "接戦しで", "explanation": "清音を濁音に変えた誤り。"},
        {"form": "接戦してて", "explanation": "「て」形にさらに「て」を付け足した重複誤り。"}
      ]
    }
  ],
  "primary_collocate": "接戦を繰り広げる",
  "collocation_distractors": [
    {"word": "接戦を勝つ", "explanation": "「接戦に勝つ」が正しく、助詞「を」は不適切。"},
    {"word": "接戦を負ける", "explanation": "「接戦に負ける」が正しく、助詞「を」は不適切。"},
    {"word": "接戦を試合する", "explanation": "「試合する」は「接戦」と組み合わせず、通常「接戦を繰り広げる」などを使う。"}
  ],
  "collocation_wrong_collocate": {
    "word": "接戦を遊ぶ",
    "explanation": "「遊ぶ」は娯楽的な活動に使われ、真剣な勝負である「接戦」とは結びつかない。"
  },
  "cloze_distractors": [
    {"word": "始めた", "explanation": "「始める」は開始を意味し、接戦を「制する」（勝ち取る）とは意味が異なる。"},
    {"word": "続けた", "explanation": "「続ける」は継続を表し、結果を決める動作ではない。"},
    {"word": "逃した", "explanation": "「逃す」は機会を失う意味で、接戦を勝ち取るという文脈に合わない。"}
  ],
  "discrimination_wrong_sentences": [
    {"sentence": "接戦を食べた。", "reason": "「食べる」の目的語には食べ物が必要で、抽象的な名詞「接戦」は不適格（誤った項構造）。"},
    {"sentence": "接戦が高い。", "reason": "「高い」は価格や高さに用いる形容詞であり、試合の性質を表すのには不適切（誤ったコロケーション）。"},
    {"sentence": "昨日の試合は接戦でしたが、大差で勝ちました。", "reason": "「接戦」は僅差の試合を意味するのに「大差」と矛盾する（意味的整合性の欠如）。"}
  ],
  "spot_incorrect": {
    "sentence": "彼は接戦を練習した。",
    "error_description": "「練習する」の目的語として「接戦」は不自然。通常は「接戦に備えて練習する」などとする。",
    "corrected": "彼は接戦に備えて練習した。"
  },
  "word_family_forms": ["接戦する", "接戦"],
  "word_family_fake_forms": [
    {"form": "接戦性", "explanation": "「～性」は性質を表す接尾辞だが、「接戦」から派生した形は存在しない。"},
    {"form": "接戦化", "explanation": "「～化」は変化を表すが、「接戦化」という語は一般的でない。"},
    {"form": "接戦的", "explanation": "「～的」は形容動詞を作るが、「接戦的」という語は標準的でない。"}
  ],
  "syn_ant_candidates": [
    {"word": "激戦", "relationship": "synonym"},
    {"word": "拮抗", "relationship": "synonym"},
    {"word": "好試合", "relationship": "synonym"},
    {"word": "大差", "relationship": "antonym"}
  ],
  "particle_candidates": {
    "sentence": "このチーム（　）の接戦が楽しみだ。",
    "particles": [
      {"particle": "と", "correct": true, "explanation": "「（人）との接戦」で、相手を表す格助詞「と」が正しい。"},
      {"particle": "に", "correct": false, "explanation": "「に」は方向や対象を示すが、この文では「との」が適切。"},
      {"particle": "で", "correct": false, "explanation": "「で」は場所や手段を表し、相手を指定しない。"},
      {"particle": "が", "correct": false, "explanation": "「が」は主格を表すが、ここでは相手を表す助詞が必要。"}
    ]
  }
}
